questions.question:
What does the following C function return for f(7)?

int f(int n) {
    if (n <= 1) return 1;
    return n * f(n - 2);
}

What is printed by the following C code?

int a[] = {10, 20, 30, 40, 50};
int *p = a + 1;
printf("%d", *(p + 2) + p[-1]);

What is printed by the following C program?

int g(void) { static int c = 0; c += 2; return c; }
int main(void) {
    int s = 0;
    for (int i = 0; i < 3; i++) s += g();
    printf("%d", s);
    return 0;
}

What is the time complexity of the following code fragment in terms of n?

for (i = 1; i < n; i *= 2)
    for (j = 0; j < i; j++)
        count++;

What does the following C function return for f(2026)?

int f(int n) {
    if (n == 0) return 0;
    return n % 10 + f(n / 10);
}

What is printed by the following C code?

int x = 5;
int *p = &x;
int **q = &p;
**q = 10;
*p = *p + 1;
printf("%d", x);

What is printed when the following function is called three times in succession?

void f(void) {
    static int a = 1;
    int b = 1;
    a++; b++;
    printf("%d%d ", a, b);
}

What is the time complexity of the following code in terms of n?

for (i = 1; i <= n; i++)
    for (j = 1; j <= n; j += i)
        count++;

Semaphores S = 1 and T = 0 are shared by two processes:

P1: while (1) { wait(S); print("0"); signal(T); }
P2: while (1) { wait(T); print("1"); signal(S); }

Which output sequence is produced?
